    'Nếu giá dịch vụ của API giống giá tiền tệ của bạn, hãy nhập 1. Nếu website bạn sử dụng USD nhưng giá dịch vụ API là VND, hãy nhập tỷ giá của 1 VND ~0,000038. Nếu giá của bạn là VND nhưng giá của API là USD, hãy nhập tỷ giá của 1 USD ~26.000' => 'Nếu giá dịch vụ của API giống giá tiền tệ của bạn, hãy nhập 1. Nếu website bạn sử dụng USD nhưng giá dịch vụ API là VND, hãy nhập tỷ giá của 1 VND ~0,000038. Nếu giá của bạn là VND nhưng giá của API là USD, hãy nhập tỷ giá của 1 USD ~26.000',
    'Nếu không chọn gì, mặc định sẽ hiển thị tất cả các tab.' => 'Nếu không chọn gì, mặc định sẽ hiển thị tất cả các tab.',
